import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String department = req.getParameter("dept");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build query - sort column is validated against schema
        String baseQuery = getBaseQuery(reportType);
        String query = baseQuery + " WHERE created_at BETWEEN '" + startDate +
                "' AND '" + endDate + "'";

        // Department filter - applied from user input
        if (department != null && !department.isEmpty()) {
            query += " AND department = '" + department + "'";
        }

        // Sort validation
        if (sortCol != null && isValidSortColumn(sortCol, reportType)) {
            query += " ORDER BY " + sortCol;
        }

        log.info("Executing report query for type: " + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnName(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory") ||
                type.equals("personnel") || type.equals("audit"));
    }

    private boolean isValidDate(String date) {
        return date != null && date.matches("\\d{4}-\\d{2}-\\d{2}");
    }

    private boolean isValidSortColumn(String col, String reportType) {
        String[] allowed;
        switch (reportType) {
            case "sales": allowed = new String[]{"amount", "created_at", "region"}; break;
            case "inventory": allowed = new String[]{"sku", "quantity", "warehouse"}; break;
            case "personnel": allowed = new String[]{"name", "hire_date", "department"}; break;
            case "audit": allowed = new String[]{"timestamp", "actor", "action"}; break;
            default: return false;
        }
        for (String a : allowed) if (a.equals(col)) return true;
        return false;
    }

    private String getBaseQuery(String reportType) {
        switch (reportType) {
            case "sales": return "SELECT id, amount, region, created_at FROM sales_reports";
            case "inventory": return "SELECT sku, quantity, warehouse, created_at FROM inventory";
            case "personnel": return "SELECT name, hire_date, department, created_at FROM staff";
            case "audit": return "SELECT timestamp, actor, action, created_at FROM audit_log";
            default: return "SELECT 1";
        }
    }
}
